/**
 * Messekalender – kommende Leitmessen je Stadt (IDs aus config/locations.ts).
 *
 * Nur Termine aus offiziellen Quellen (Veranstalter, Messegelände, AUMA). Die Website zeigt je Stadt
 * automatisch die nächste Ausgabe, deren Ende noch nicht vorbei ist (lib/trade-fairs.ts).
 * Neue Ausgaben einfach ergänzen; `npm run fairs:check` meldet Städte, denen bald die Termine ausgehen.
 */
export type TradeFair = {
  city: string;
  /** offizieller Name ohne Jahreszahl */
  name: string;
  /** Marke/Kurzname, z. B. „bauma“ */
  short: string;
  sector: { de: string; en: string };
  venue: string;
  /** YYYY-MM-DD (Ortsdatum) */
  start: string;
  end: string;
  /** offizielle Website der Messe */
  url: string;
  /** Seite mit der Terminangabe */
  source: string;
};

